insecure_values := {"false", "HTTP", "none", "plaintext", "tcp"}

# Helper to check if a string contains insecure patterns
check_insecure_string(str) {
    regex.match(sprintf("(?i).*%s.*", [insecure_protocols[_]]), str)
}

