    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]
    check_unencrypted_protocol(attr.value)

    result := {
        "type": "sec_https",
        "element": attr,
        "path": parent.path,
        "description": "Cleartext transmission of sensitive information - Attribute uses unencrypted protocol. (CWE-319)"
    }
}

Glitch_Analysis[result] {
    parent := glitch_lib._gather_parent_unit_blocks[_]
    parent.path != ""

    # Check for specific encryption disabling attributes
    atomic_units := glitch_lib.all_atomic_units(parent)
    node := atomic_units[_]

    attrs := glitch_lib.all_attributes(node)
    attr := attrs[_]

    # Check for attributes that disable certificate validation or encryption
    check_encryption_disabling(attr)

    result := {
        "type": "sec_https",
        "element": attr,
        "path": parent.path,
        "description": "Cleartext transmission of sensitive information - Attribute disables encryption/certificate validation. (CWE-319)"
    }
}

# Helper function to check for unencrypted protocols in values
check_unencrypted_protocol(value) {
    # Check if value contains string with unencrypted protocol
    glitch_lib.traverse(value, "(?i)^(http|ftp|smtp)://")
}

# Helper function to check for encryption disabling settings
check_encryption_disabling(attr) {
    # Check attribute names that commonly disable encryption
    attr.name == "validate_certs"
    attr.value.ir_type == "String"
    attr.value.value == "no"
} else {
    attr.name == "validate_certs"
    attr.value.ir_type == "Boolean"
    attr.value.value == false
} else {
    # Check for protocol set to http
    attr.name == "protocol"
    attr.value.ir_type == "String"
    attr.value.value == "http"
} else {
    # Check for any attribute with ssl, tls, or encryption in name set to false
    regex.match("(?i)(ssl|tls|encrypt|https|secure)", attr.name)
    attr.value.ir_type == "Boolean"
    attr.value.value == false
} else {
    regex.match("(?i)(ssl|tls|encrypt|https|secure)", attr.name)
    attr.value.ir_type == "String"
    attr.value.value == "no"
}

